use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Extracts content between the specified XML-style tags"] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `text` - The text to extract content from"] # [doc = " * `tag_name` - The name of the XML tag (without angle brackets)"] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " * `Some(&str)` containing the extracted content if tags are found"] # [doc = " * `None` if the tags are not found"] pub fn extract_tag_content < 'a > (text : & 'a str , tag_name : & str) -> Option < & 'a str > { let opening_tag = format ! ("<{tag_name}>" ,) ; let closing_tag = format ! ("</{tag_name}>") ; # [allow (clippy :: collapsible_if)] if let Some (start_idx) = text . find (& opening_tag) { if let Some (end_idx) = text . rfind (& closing_tag) { let content_start = start_idx + opening_tag . len () ; if content_start < end_idx { return text . get (content_start .. end_idx) . map (| s | s . trim ()) ; } } } None }